const norm = (w: string) => w.toLowerCase().replace(/[.,!?"“”]/g, "");
/* Aspect from the English gloss, so every verb form gets its shade (0 · ½ · 1). Commands and bare roots get none. */
function aspectOf(m: string): Token["aspect"] | undefined {
  const g = m.toLowerCase();
  if (/\b(command|invitation|bare root|please|let's|come here|take care)\b/.test(g)) return undefined;
  if (/^(will |to )|not yet/.test(g)) return "contemplated";
  if (/\b(is|are|am) \w+ing\b|\bongoing\b|\w+ing\b/.test(g)) return "ongoing";
  if (/\b(went|ate|drank|bought|got|took|sat|laughed|arrived|stopped|paid|gave|saw|said|asked|slept|woke|came|lit|told|danced|sang|was|were|did|made|put|sliced|stirred|waited|cleaned|helped|played|called|decided|remembered|confused|used|forced|lifted|walked|looked|listened|rode|hugged|boarded|reached|answered|studied|cooked|warmed)\b|ed\b|\(object focus\)$/.test(g)) return "completed";
  return undefined;
}

const tk = (list: TT[]): Token[] => list.map((x) => {
  const [t, role, m, note] = typeof x === "string" ? (DICT[norm(x)] ? [x, DICT[norm(x)][1], DICT[norm(x)][2], DICT[norm(x)][3]] as T : (() => { throw new Error(`stories: no DICT entry for "${x}"`); })()) : x;
  const tok: Token = note ? { t, role, m, note } : { t, role, m };
  if (role === "action") { const a = aspectOf(m); if (a) tok.aspect = a; }
  return tok;
});

let seq = 0;
function line(storyId: string, text: string, gloss: string, tokens: TT[], voice?: "A" | "B"): StoryLine {
  seq += 1;
  return { id: `${storyId}-${String(seq).padStart(2, "0")}`, text, gloss, tokens: tk(tokens), voice };
}

